const xml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uri=svg=>'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
const hash=s=>[...String(s)].reduce((a,c)=>(a*31+c.codePointAt(0))>>>0,0);
const palettes={math:['#0F766E','#73C4A7'],science:['#316A5B','#B7CD7A'],arabic:['#8B5145','#E7B897'],english:['#425A91','#A8BEE4'],islamic:['#665C8B','#C8B8D9'],social:['#9B6E31','#EBD18B'],physics:['#265E7D','#7ACBD2'],chemistry:['#6E536E','#D9A5B8']};
const motifs={math:'<path d="M180 215 280 65 380 215Z M180 215h200 M280 65v150"/><circle cx="280" cy="150" r="60"/>',science:'<path d="M280 220V100 M280 170q-110-10-90-90 90-5 90 90 M280 140q100-5 90-80-90-5-90 80"/>',arabic:'<path d="M150 85q65-20 130 10 65-30 130-10v130q-65-20-130 10-65-30-130-10Z M280 95v130 M175 120h65 M175 150h65 M315 120h65 M315 150h65"/>',english:'<path d="M160 70h230v140H270l-60 40v-40h-50Z M195 115h160 M195 150h105"/>',islamic:'<path d="m280 50 30 60 65-10-10 65 55 35-65 20-15 65-60-35-60 35-15-65-65-20 55-35-10-65 65 10Z"/>',social:'<circle cx="280" cy="150" r="95"/><ellipse cx="280" cy="150" rx="45" ry="95"/><path d="M185 150h190 M200 105h160 M200 195h160"/>',physics:'<ellipse cx="280" cy="150" rx="115" ry="40"/><ellipse cx="280" cy="150" rx="115" ry="40" transform="rotate(60 280 150)"/><ellipse cx="280" cy="150" rx="115" ry="40" transform="rotate(120 280 150)"/><circle cx="280" cy="150" r="12"/>',chemistry:'<path d="M245 50h70 M255 50v70l-65 110q-5 20 20 20h140q25 0 20-20l-65-110V50 M215 190h130"/><circle cx="270" cy="210" r="8"/><circle cx="305" cy="170" r="6"/>'};
export function courseCover(courseId,subjectId) { const [a,b]=palettes[subjectId]??palettes.math;const offset=hash(courseId)%60;return uri(`<svg xmlns="http://www.w3.org/2000/svg" width="560" height="350" viewBox="0 0 560 350"><defs><linearGradient id="g" x2="1" y2="1"><stop stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient><pattern id="p" width="28" height="28" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="white" opacity=".2"/></pattern></defs><rect width="560" height="350" fill="url(#g)"/><rect width="560" height="350" fill="url(#p)"/><circle cx="${480+offset}" cy="10" r="150" fill="white" opacity=".1"/><circle cx="20" cy="350" r="140" fill="white" opacity=".08"/><g transform="translate(0 15)" fill="none" stroke="#fff6df" stroke-width="5" stroke-linecap="round" stroke-linejoin="round">${motifs[subjectId]??motifs.math}</g><path d="M440 270h45 M462 248v45" stroke="white" opacity=".5" stroke-width="3"/></svg>`); }
// First + last name initials, skipping the "Al"/"ال" article so families do not all read "A".
const initialOf=w=>[...(w.length>3&&w.startsWith('ال')?w.slice(2):w)][0]??'';
export function initialsAvatar(name,seed) { const words=String(name??'').trim().split(/\s+/).filter(w=>w&&!/^al$/i.test(w)),initials=(words.length>1?[words[0],words.at(-1)]:words).map(initialOf).join(' ');const color=Object.values(palettes)[hash(seed)%8][0];return uri(`<svg xmlns="http://www.w3.org/2000/svg" width="120" height="120" viewBox="0 0 120 120"><rect width="120" height="120" rx="60" fill="${color}"/><circle cx="100" cy="15" r="50" fill="white" opacity=".1"/><text x="60" y="65" text-anchor="middle" dominant-baseline="middle" font-family="sans-serif" font-size="36" fill="white">${xml(initials)}</text></svg>`); }
